// Build the fact ledger for each product. This mirrors src/ledger/fact-ledger.ts.
// Nothing downstream may state a fact that is not in this list.
const BRAND_FACTS = [
  { id: 'brand.roast_days', label: 'Roasting days', value: 'Monday and Thursday' },
  { id: 'brand.ship_same_day', label: 'Ships the day it is roasted', value: 'same day' },
  { id: 'brand.location', label: 'Roastery location', value: 'Miami, FL' },
  { id: 'brand.free_shipping_threshold_usd', label: 'Free shipping threshold', value: 45 },
];

function numberSurfaces(value) {
  const out = [String(value)];
  if (Number.isInteger(value) && value >= 1000) out.push(value.toLocaleString('en-US'));
  return out;
}

const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const h = p.handle;
  const entries = [];
  const add = (sourceClass, source, label, value, surfaces) =>
    entries.push({ id: h + ':' + source, sourceClass, source, label, value, surfaces });

  const a = p.attributes || {};
  if (a.roast_level) add('attributes', 'attributes.roast_level', 'Roast level', a.roast_level, [a.roast_level]);
  if (a.origin) add('attributes', 'attributes.origin', 'Origin', a.origin, [a.origin, ...a.origin.split(/[,+]/).map(s => s.trim())]);
  if (a.process) add('attributes', 'attributes.process', 'Process', a.process, [a.process]);
  if (typeof a.altitude_masl === 'number') add('attributes', 'attributes.altitude_masl', 'Altitude (masl)', a.altitude_masl, numberSurfaces(a.altitude_masl));
  (a.tasting_notes || []).forEach((note, i) => add('attributes', 'attributes.tasting_notes[' + i + ']', 'Tasting note', note, [note]));
  if (typeof a.green_price_per_kg_usd === 'number') add('attributes', 'attributes.green_price_per_kg_usd', 'Green price per kilo (USD)', a.green_price_per_kg_usd, numberSurfaces(a.green_price_per_kg_usd));
  if (p.short_blurb) add('blurb', 'short_blurb', 'Merchant blurb', p.short_blurb, [p.short_blurb]);
  add('identity', 'title', 'Title', p.title, [p.title]);
  add('identity', 'vendor', 'Vendor', p.vendor, [p.vendor]);

  const grinds = [...new Set((p.variants || []).map(v => v.option1_grind).filter(Boolean))];
  const sizes = [...new Set((p.variants || []).map(v => v.option2_size).filter(Boolean))];
  const options = [...new Set((p.variants || []).map(v => v.option1).filter(Boolean))];
  const prices = [...new Set((p.variants || []).map(v => v.price))];
  if (grinds.length) add('variants', 'variants[].option1_grind', 'Grind options', grinds.join(', '), grinds);
  if (sizes.length) add('variants', 'variants[].option2_size', 'Size options', sizes.join(', '), sizes);
  if (options.length) add('variants', 'variants[].option1', 'Options', options.join(', '), options);
  if (prices.length) add('variants', 'variants[].price', 'Prices', prices.join(', '), prices.flatMap(numberSurfaces));

  for (const f of BRAND_FACTS) entries.push({ ...f, sourceClass: 'brand', source: f.id, surfaces: numberSurfaces(f.value).concat(String(f.value)) });

  out.push({ json: { handle: h, title: p.title, product: p, ledger: { handle: h, entries } } });
}
return out;

// Assemble the Messages API request. Mirrors src/generate/prompt.ts.
// NOTE: no temperature / top_p / top_k — those are removed on claude-opus-5 and
// sending one is a 400. Thinking is left on; the latency lever is output_config.effort.
const styleGuide = $('Config').first().json.styleGuide;
const item = $input.first().json;
const ledgerText = item.ledger.entries
  .map(e => '- id: ' + e.id + '\n  source: ' + e.source + '\n  ' + e.label + ': ' + e.value)
  .join('\n');

const system = [
  'You are the copywriter for Cerro Alto Coffee, a small direct-to-consumer roaster.',
  'You write catalog copy that sounds like the person behind the counter: plain words,',
  'second person, specific before reassuring. You never write anything you cannot point',
  'to a source for.',
  '',
  '<rules>',
  '1. Use ONLY the facts in <fact_ledger>. If a fact is not there, it does not exist.',
  '2. Never state or imply a certification. Cerro Alto is not organic, not Fair Trade,',
  '   not carbon neutral, not direct trade. Not even in passing.',
  '3. Never use: artisanal, curated, elevated, journey, passion, handcrafted, liquid gold,',
  '   exquisite, unlock.',
  '4. metaTitle at most ' + styleGuide.metaTitleMaxChars + ' characters.',
  '5. metaDescription between ' + styleGuide.metaDescriptionMin + ' and ' + styleGuide.metaDescriptionMax + ' characters, second person, no exclamation marks.',
  '6. imageAlt describes what is in the frame and never begins with "image of".',
  '7. Sentences of at most ' + styleGuide.maxSentenceWords + ' words.',
  '</rules>',
  '',
  '<example label="violation: invented fact">',
  'Grown at 2,100 meters on a smallholder farm, this Gesha lot is picked by hand.',
  'Why it fails: the ledger says 1,750 meters. Gesha, smallholder farm and picked by hand',
  'appear nowhere in the data.',
  '</example>',
  '',
  '<example label="violation: implied certification">',
  'Sustainably sourced from farms that care about the land.',
  'Why it fails: that reads as a certification claim, and Cerro Alto holds none.',
  '</example>',
].join('\n');

const user = [
  '<product>', 'handle: ' + item.handle, 'title: ' + item.title, '</product>', '',
  '<fact_ledger>', ledgerText, '</fact_ledger>', '',
  'Write the description, meta title, meta description and image alt text for this product.',
].join('\n');

return [{ json: {
  handle: item.handle,
  ledger: item.ledger,
  body: {
    model: 'claude-opus-5',
    max_tokens: 4096,
    system: system,
    messages: [{ role: 'user', content: user }],
    thinking: { type: 'adaptive' },
    output_config: {
      effort: 'medium',
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            bodyHtml: { type: 'string' },
            metaTitle: { type: 'string' },
            metaDescription: { type: 'string' },
            imageAlt: { type: 'string' },
            claims: { type: 'array', items: { type: 'object', properties: { text: { type: 'string' }, factId: { type: 'string' } }, required: ['text', 'factId'], additionalProperties: false } },
          },
          required: ['bodyHtml', 'metaTitle', 'metaDescription', 'imageAlt', 'claims'],
          additionalProperties: false,
        },
      },
    },
  },
} }];

// The gate. Mirrors src/validate/rules.ts + src/validate/provenance.ts.
// A product that fails here publishes nothing at all.
const styleGuide = $('Config').first().json.styleGuide;
const BANNED = ['artisanal','curated','elevated','journey','passion','handcrafted','liquid gold','game-changing','exquisite','unlock'];
const CERTIFICATION = ['organic','certified','certification','fair trade','fairtrade','carbon neutral','direct trade','rainforest alliance','bird friendly','sustainably sourced','ethically sourced','responsibly sourced','eco friendly','pesticide free','regenerative','biodynamic'];
const DOMAIN = ['washed','natural','honey','anaerobic','sugarcane','decaf','geisha','gesha','caturra','castillo','bourbon','typica','colombia','huila','narino','tolima','ethiopia','kenya','light','medium','dark','plum','brown sugar','cane sugar','orange','raspberry','hibiscus','chocolate','dark chocolate','milk chocolate','molasses','walnut','almond','red apple','caramel','pear','cocoa','blueberry','cherry','peach','jasmine','bergamot','citrus','black tea','single origin','microlot','smallholder','estate','shade grown','hand picked','sun dried','small batch','espresso','filter','french press','whole bean','ceramic','steel','plastic','bleached'];
const SECOND_PERSON = ['you','your','yours','yourself'];

const norm = s => ' ' + String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + ' ';
const has = (term, text) => norm(text).indexOf(norm(term)) !== -1;
const canonical = raw => {
  const cleaned = String(raw).replace(/,/g, '').replace(/[^0-9.]/g, '').replace(/^\.+|\.+$/g, '');
  return /^\d+(\.\d+)?$/.test(cleaned) ? String(parseFloat(cleaned)) : null;
};

const item = $input.first().json;
const raw = item.content && item.content[0] && item.content[0].text ? item.content[0].text : item.text;
let copy;
try { copy = JSON.parse(raw); } catch (e) {
  return [{ json: { handle: item.handle, passed: false, violations: [{ ruleId: 'GEN', message: 'model did not return JSON' }] } }];
}

const ledger = $('Build fact ledger').all().find(x => x.json.handle === item.handle).json.ledger;
const ledgerText = norm(ledger.entries.flatMap(e => [...(e.surfaces || []), String(e.value)]).join(' | '));
const ledgerNumbers = new Set();
for (const e of ledger.entries) {
  for (const s of [...(e.surfaces || []), String(e.value)]) {
    const m = String(s).match(/\d[\d.,]*/g) || [];
    for (const token of m) { const c = canonical(token); if (c) ledgerNumbers.add(c); }
  }
}

const fields = { bodyHtml: copy.bodyHtml, metaTitle: copy.metaTitle, metaDescription: copy.metaDescription, imageAlt: copy.imageAlt };
const violations = [];
const plain = s => String(s || '').replace(/<[^>]+>/g, ' ');

for (const [field, value] of Object.entries(fields)) {
  const text = plain(value);
  for (const term of BANNED) if (has(term, text)) violations.push({ ruleId: 'AC-01', field, message: 'banned brand word "' + term + '"' });
  for (const term of CERTIFICATION) if (has(term, text)) violations.push({ ruleId: 'AC-02', field, message: 'certification claim "' + term + '"' });
  if (/[!\u00a1]/.test(text)) violations.push({ ruleId: 'AC-07a', field, message: 'exclamation mark' });
  for (const token of text.match(/\d[\d.,]*/g) || []) {
    const c = canonical(token);
    if (c && !ledgerNumbers.has(c)) violations.push({ ruleId: 'AC-06a', field, message: 'figure "' + token + '" is not in the fact ledger' });
  }
  for (const term of DOMAIN) if (has(term, text) && ledgerText.indexOf(norm(term)) === -1) {
    violations.push({ ruleId: 'AC-06b', field, message: '"' + term + '" is a claim nothing in the ledger supports' });
  }
}
if (copy.metaTitle.length > styleGuide.metaTitleMaxChars) violations.push({ ruleId: 'AC-03', field: 'metaTitle', message: 'meta title is ' + copy.metaTitle.length + ' characters' });
if (copy.metaDescription.length < styleGuide.metaDescriptionMin || copy.metaDescription.length > styleGuide.metaDescriptionMax) violations.push({ ruleId: 'AC-04', field: 'metaDescription', message: 'meta description is ' + copy.metaDescription.length + ' characters' });
if (/^(image|photo|picture) of/i.test(copy.imageAlt.trim())) violations.push({ ruleId: 'AC-05', field: 'imageAlt', message: 'alt text announces that it is an image' });
for (const field of ['bodyHtml', 'metaDescription']) {
  if (!SECOND_PERSON.some(m => has(m, plain(fields[field])))) violations.push({ ruleId: 'AC-07b', field, message: 'no second-person address' });
}
for (const sentence of plain(copy.bodyHtml).split(/(?<=[.!?])\s+/)) {
  const words = sentence.trim().split(/\s+/).filter(Boolean).length;
  if (words > styleGuide.maxSentenceWords) violations.push({ ruleId: 'AC-08a', field: 'bodyHtml', message: 'sentence runs to ' + words + ' words' });
}

return [{ json: { handle: item.handle, copy, violations, passed: violations.length === 0 } }];

// Collect the run into one artifact. Quarantined products carry no copy forward.
const results = $input.all().map(i => i.json);
const publishable = results.filter(r => r.passed);
return [{ json: {
  anchorDate: $('Config').first().json.anchorDate,
  locale: $('Config').first().json.locale,
  generator: 'claude-opus-5',
  total: results.length,
  publishable: publishable.length,
  quarantined: results.length - publishable.length,
  products: results.map(r => ({ handle: r.handle, status: r.passed ? 'publishable' : 'quarantined', copy: r.passed ? r.copy : null, violations: r.violations })),
} }];
